import gridColours from "../data/grid-colours.json";

interface ImageSharpEdge {
  node: {
    publicURL: string
    childImageSharp: {
      thumb: IGatsbyImageData
      full: IGatsbyImageData
    }
  }
}

interface ImageNode {
  childImageSharp: {
    thumb: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    images: {
      edges: ImageSharpEdge[]
    }
    pictureMeLogo: {
      nodes: ImageNode[]
    }
    circlesLogo: {
      nodes: ImageNode[]
    }
    musartLogo: {
      nodes: ImageNode[]
    }
    shuffleCards: {
      nodes: {
        childImageSharp: {
          thumb: IGatsbyImageData
          original: { width: number; height: number }
        }
      }[]
    }
    mosaicCard: {
      nodes: ImageNode[]
    }
  }
}

// Card background for Bird Shuffle — bird photo split into a shuffled 3x3 tile grid
const SHUFFLE_ORDER = [2, 7, 4, 6, 0, 8, 1, 5, 3] // fixed shuffle so it looks good

const BirdShuffleCardBg: React.FC<{ imageSrc: string }> = ({ imageSrc }) => (
  <div className="shuffle-card-bg">
    {SHUFFLE_ORDER.map((tileValue, i) => {
      const col = tileValue % 3
      const row = Math.floor(tileValue / 3)
      return (
        <div
          key={i}
          className="shuffle-card-bg__tile"
          style={{
            backgroundImage: `url(${imageSrc})`,
            backgroundSize: '300% 300%',
            backgroundPosition: `${col * 50}% ${row * 50}%`,
          }}
        />
      )
    })}
  </div>
)

// Card background for Circle Match — 5x5 grid of coloured dots
const CircleMatchCardBg: React.FC = () => {
  const dots = React.useMemo(() => {
    const shuffled = [...gridColours]
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
    }
    // 25 cells, some filled some empty
    return Array.from({ length: 25 }, (_, i) =>
      i < 10 ? shuffled[i % shuffled.length] : null
    ).sort(() => Math.random() - 0.5)
  }, [])

  return (
    <div className="circle-match-card-bg">
      {dots.map((colour, i) => (
        <div
          key={i}
          className="circle-match-card-bg__dot"
          style={colour
            ? { '--dot-colour': colour } as React.CSSProperties
            : { opacity: 0.15, background: '#1E3A5F' }
          }
        />
      ))}
    </div>
  )
}

const DeveloperPage: React.FC<PageProps> = ({ data }) => {
  const [lightboxIndex, setLightboxIndex] = React.useState(-1)

  // Transform images for lightbox
  const lightboxSlides = data.images.edges.map(({ node }) => {
    return {
      src: node.publicURL,
    }
  })

  const logoImage = data.pictureMeLogo.nodes[0]
    ? getImage(data.pictureMeLogo.nodes[0].childImageSharp.thumb)
    : null

  const circlesLogo = data.circlesLogo.nodes[0]
    ? getImage(data.circlesLogo.nodes[0].childImageSharp.thumb)
    : null

  const musartLogo = data.musartLogo.nodes[0]
    ? getImage(data.musartLogo.nodes[0].childImageSharp.thumb)
    : null

  // Pick a random bird photo for the shuffle card
  const shuffleCardSrc = React.useMemo(() => {
    const portraits = data.shuffleCards.nodes.filter(n => {
      const { width, height } = n.childImageSharp.original
      return height >= width // portrait orientation works best in a square card
    })
    const pool = portraits.length > 0 ? portraits : data.shuffleCards.nodes
    const pick = pool[Math.floor(Math.random() * pool.length)]
    const image = pick ? getImage(pick.childImageSharp.thumb) : null
    return image?.images?.fallback?.src || ''
  }, [data.shuffleCards.nodes])

  const mosaicCardImage = data.mosaicCard.nodes[0]
    ? getImage(data.mosaicCard.nodes[0].childImageSharp.thumb)
    : null

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <h1>Code</h1>
        <p>Interactive experiments built for fun &mdash; combining my love of photography with code.</p>
        <AccentDots />
      </div>
      <div className="galleries-container">
        <div className="galleries-grid">
          <Link to="/bird-shuffle" className="gallery-card">
            <BirdShuffleCardBg imageSrc={shuffleCardSrc} />
            <div className="gallery-info">
              <h2>Bird Shuffle</h2>
              <p>Shuffle the tiles, discover the bird</p>
            </div>
          </Link>
          <Link to="/bird-mosaic" className="gallery-card gallery-card--hide-mobile">
            {mosaicCardImage && (
              <GatsbyImage
                image={mosaicCardImage}
                alt="Bird Mosaic"
                className="gallery-cover"
              />
            )}
            <div className="gallery-info">
              <h2>Bird Mosaic</h2>
              <p>Photos arranged into a bird silhouette</p>
            </div>
          </Link>
          <Link to="/circle-match" className="gallery-card">
            <CircleMatchCardBg />
            <div className="gallery-info">
              <h2>Circle Match</h2>
              <p>A colour sequence memory game</p>
            </div>
          </Link>
        </div>
      </div>
      {/* <div className="case-study-card-wrap">
        <Link to="/developer/picture-me" className="case-study-card">
          {logoImage && (
            <div className="case-study-card__logo-wrap">
              <GatsbyImage
                image={logoImage}
                alt="Picture Me"
                className="case-study-card__logo"
              />
            </div>
          )}
          <div className="case-study-card__info">
            <h3>Picture Me</h3>
            <p>A full-stack MEAN app — an interactive photo mosaic representing the layers of a person.</p>
          </div>
        </Link>
      </div> */}
      {/* <div className="case-study-card-wrap">
        <Link to="/developer/circles-game" className="case-study-card">
          {circlesLogo && (
            <div className="case-study-card__logo-wrap">
              <GatsbyImage
                image={circlesLogo}
                alt="Circles Game"
                className="case-study-card__logo"
              />
            </div>
          )}
          <div className="case-study-card__info">
            <h3>Circles Game</h3>
            <p>A visual memory game — memorise the coloured circle sequence and repeat it back.</p>
          </div>
        </Link>
      </div> */}
      {/* <div className="case-study-card-wrap">
        <Link to="/developer/musart" className="case-study-card">
          {musartLogo && (
            <div className="case-study-card__logo-wrap">
              <GatsbyImage
                image={musartLogo}
                alt="Musart"
                className="case-study-card__logo case-study-card__logo--large"
              />
            </div>
          )}
          <div className="case-study-card__info">
            <h3>Musart</h3>
            <p>A Ruby on Rails community platform for artists working with visuals and sound.</p>
          </div>
        </Link>
      </div> */}
      {/* {data.images.edges.length > 0 && (
        <>
          <div className="masonry-gallery">
            {data.images.edges.map(({ node }, index) => {
              const image = getImage(node.childImageSharp.thumb)
              if (!image) return null

              return (
                <div
                  key={index}
                  className="gallery-item"
                  onClick={() => setLightboxIndex(index)}
                >
                  <GatsbyImage
                    image={image}
                    alt={`Developer - Image ${index + 1}`}
                    className="gallery-thumb"
                  />
                </div>
              )
            })}
          </div>
          <Lightbox
            open={lightboxIndex >= 0}
            close={() => setLightboxIndex(-1)}
            index={lightboxIndex}
            slides={lightboxSlides}
          />
        </>
      )} */}
      <Footer />
    </div>
  );
}

export const pageQuery = graphql`
  query DeveloperImagesQuery {
    images: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { nin: ["picture-me", "circles-game", "musart"] }
      }
      sort: { name: ASC }
    ) {
      edges {
        node {
          publicURL
          childImageSharp {
            thumb: gatsbyImageData(
              width: 600
              placeholder: BLURRED
              aspectRatio: 1
            )
            full: gatsbyImageData(layout: FULL_WIDTH)
          }
        }
      }
    }
    pictureMeLogo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "picture-me" }
        name: { eq: "picture-me-logo-small" }
      }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(width: 600, placeholder: BLURRED)
        }
      }
    }
    circlesLogo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "circles-game" }
        name: { eq: "colour_game_logo_small" }
      }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(width: 600, placeholder: BLURRED)
        }
      }
    }
    musartLogo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "musart" }
        name: { eq: "musart" }
      }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(width: 600, placeholder: BLURRED)
        }
      }
    }
    shuffleCards: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        extension: { regex: "/(jpg|jpeg|png)/" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(
            width: 400
            height: 400
            placeholder: BLURRED
            transformOptions: { cropFocus: ATTENTION }
          )
          original { width height }
        }
      }
    }
    mosaicCard: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        relativeDirectory: { eq: "birds-by-water" }
        name: { eq: "photo1" }
      }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(
            width: 400
            height: 260
            placeholder: BLURRED
            transformOptions: { cropFocus: ATTENTION }
          )
        }
      }
    }
  }
`

export default DeveloperPage;
